'use client';
import { useEffect, useState } from 'react';
import { api } from '@/lib/api';
import { toast } from 'sonner';
type Profile = { subscriptionPlan?: string; subscriptionExpiresAt?: string | null };
export default function Subscription() {
  const [busy, B] = useState(false), [profile, P] = useState<Profile | null>(null);
  useEffect(() => { api<Profile>('/profile').then(P).catch(e => toast.error(e.message)); }, []);
  async function openBilling() { B(true); try { const r = await api<{ url: string }>('/payments/create-portal-session', { method: 'POST', body: '{}' }); if (r.url) location.href = r.url; } catch (e: any) { toast.error(e.message); } finally { B(false); } }
  async function upgrade() { B(true); try { const r = await api<{ url: string }>('/payments/create-checkout-session', { method: 'POST', body: '{}' }); if (r.url) location.href = r.url; else toast.error('Checkout session unavailable'); } catch (e: any) { toast.error(e.message); } finally { B(false); } }
  return <main className="section"><p className="hero-kicker">GROW YOUR RESTAURANT</p><h1>Subscription</h1><p className="muted">Choose the plan that fits your restaurant.</p><div className="grid" style={{ gridTemplateColumns: '1fr 1fr', marginTop: 22 }}><div className="card"><p className="hero-kicker">STARTER</p><h2>Free</h2><h3>৳0</h3><ul><li>Maximum 3 active menu items</li><li>Basic vendor dashboard</li><li>Customer order management</li></ul>{profile?.subscriptionPlan !== 'premium' && <span className="status-pill">Your current plan</span>}</div><div className="card" style={{ border: '2px solid var(--brand)' }}><p className="hero-kicker">MORE ROOM TO GROW</p><h2>Premium <span className="status-pill status-approved">✦</span></h2><ul><li>Unlimited active menu items</li><li>Premium vendor badge</li><li>Featured menu placement on homepage</li><li>All Free plan features</li></ul>{profile?.subscriptionPlan === 'premium' ? <><span className="status-pill status-approved">Your current plan</span><p className="muted">{profile.subscriptionExpiresAt ? `Renews / expires: ${new Date(profile.subscriptionExpiresAt).toLocaleDateString()}` : 'Active subscription'}</p><button className="btn secondary" disabled={busy} onClick={openBilling}>{busy ? 'Opening…' : 'Manage Subscription'}</button></> : <button className="btn" disabled={busy} onClick={upgrade}>{busy ? 'Redirecting…' : 'Upgrade to Premium'}</button>}</div></div><p className="muted" style={{ marginTop: 18 }}>Premium access is activated only after the server verifies Stripe's webhook event. Stripe is used only for vendor subscriptions, not customer pizza orders.</p></main>;
}
